h,w=17,30
src=[[0]*w for _ in range(h)]
shapes={
4: [(0,c) for c in range(14,19)]+[(1,16)]+[(2,c) for c in range(15,18)]+[(3,c) for c in range(14,19)]+[(4,16)],
8: [(0,c) for c in range(21,26)]+[(1,23)]+[(2,c) for c in range(22,25)]+[(3,c) for c in range(21,26)]+[(4,23)],
3: [(0,c) for c in range(2,7)]+[(1,4)]+[(2,c) for c in range(3,6)]+[(3,c) for c in range(2,7)]+[(4,4)],
1: [(0,c) for c in range(9,14)]+[(1,11)]+[(2,c) for c in range(10,13)]+[(3,c) for c in range(9,14)]+[(4,11)]}
starts={4:2,8:7,3:9,1:12}
for color, cells in shapes.items():
    for dr,c in cells:
        r=2+dr
        src[r][c]=color
# translate each lower object upward so each bounding box starts at row 2
out=[[0]*w for _ in range(h)]
for color,cells in shapes.items():
    for dr,c in cells:
        out[2+dr][c]=color
for color in (8,3,1):
    delta=starts[color]-2
    for r in range(h):
        for c in range(w):
            if src[r][c]==color: out[r-delta][c]=color
assert len(out)==17 and all(len(x)==30 for x in out)
print(json.dumps(out,separators=(',',':')))
print('changed',sum(src[r][c]!=out[r][c] for r in range(h) for c in range(w)))
